CREATE TABLE "feed_post_polls" ("post_id" uuid PRIMARY KEY REFERENCES "feed_posts"("id") ON DELETE CASCADE, "question" varchar(280) NOT NULL, "allow_multiple" boolean DEFAULT false NOT NULL, "closes_at" timestamp with time zone NOT NULL);
CREATE TABLE "feed_post_poll_options" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "post_id" uuid NOT NULL REFERENCES "feed_post_polls"("post_id") ON DELETE CASCADE, "label" varchar(100) NOT NULL, "position" integer NOT NULL);
CREATE UNIQUE INDEX "feed_poll_option_position_unique" ON "feed_post_poll_options" ("post_id", "position");
CREATE TABLE "feed_post_poll_votes" ("option_id" uuid NOT NULL REFERENCES "feed_post_poll_options"("id") ON DELETE CASCADE, "user_id" uuid NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "created_at" timestamp with time zone DEFAULT now() NOT NULL, PRIMARY KEY ("option_id", "user_id"));
CREATE TABLE "story_views" ("story_id" uuid NOT NULL REFERENCES "stories"("id") ON DELETE CASCADE, "viewer_id" uuid NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "viewed_at" timestamp with time zone DEFAULT now() NOT NULL, PRIMARY KEY ("story_id", "viewer_id"));
CREATE TABLE "story_likes" ("story_id" uuid NOT NULL REFERENCES "stories"("id") ON DELETE CASCADE, "user_id" uuid NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "created_at" timestamp with time zone DEFAULT now() NOT NULL, PRIMARY KEY ("story_id", "user_id"));
CREATE TABLE "story_replies" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "story_id" uuid NOT NULL REFERENCES "stories"("id") ON DELETE CASCADE, "sender_id" uuid NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "recipient_id" uuid NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "body" varchar(500) NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE INDEX "story_replies_recipient_created_idx" ON "story_replies" ("recipient_id", "created_at");
